// generated by plugin/scripts/build.mjs from cli/src (piezas 0.7.4); do not edit by hand
// Part of the piezas CLI (see index.js).
//
// ===========================================================================
// The workspace guard: a Piezas app changes only its own folder
// ===========================================================================
//
// An AI building an app once followed a wrong contract line and then "fixed"
// Piezas itself: it edited the Piezas backend repo next door, built and packed
// its own copy of @piezas/sdk into vendor/, and wrote app code calling Piezas
// addresses that do not exist. Each step looked like progress; together they
// produced an app that only works on that one laptop.
//
// So, inside a Piezas project (the folder with piezas.manifest.json, or
// .piezas/state.json):
//   - the AI's writes go only inside the project folder and the OS temp
//     folder — through the edit tools AND the shell (redirects, tee, cp/mv,
//     sed -i, rm, mkdir, git -C ..., `cd <elsewhere> && ...`). Reading stays
//     open everywhere;
//   - even inside, Piezas's own packages pause the AI: node_modules/@piezas,
//     a vendored copy (vendor/*piezas*, *piezas-sdk*.tgz), packing or linking
//     one, or installing @piezas/* from a file, link, git URL or tarball.
//
// The owner, and only the owner, can allow outside changes for one session by
// typing "allow outside changes" (recorded by the UserPromptSubmit hook from
// their own message, the same way "deploy anyway" is). The same phrase also
// unlocks changing the Piezas toolkit copy inside the project, after the AI has
// explained the risk. The AI cannot write that record. A deploy with a homemade
// toolkit still pauses for the owner's own "deploy anyway".
import { existsSync, lstatSync, mkdirSync, readFileSync, readdirSync, readlinkSync, realpathSync, writeFileSync } from 'fs';
import { homedir, tmpdir } from 'os';
import { createHash } from 'crypto';
import { basename, dirname, isAbsolute, join, relative, resolve, sep } from 'path';
import {
  DEPLOY_RISK_FILE,
  KEY_MINT_FILE,
  DEPLOY_LINK_FILE,
  LINK_CONFIRM_FILE,
  OWNER_APPROVALS_FILE,
  PROJECT_HOOK_MARKER,
  PROJECT_HOOK_SETTINGS,
  QUALITY_ATTESTATION_FILE,
  QUALITY_FINDINGS_FILE,
  QUALITY_SCAN_DIR,
  STATE_DIR,
} from './constants.js';
// Functions only, used at call time: the import cycle with these modules is safe.
import { stripHeredocBodies } from './guards.js';
import { childProjects } from './protocol.js';
import { fileProblem, foldPath, inHookStateDir, relKey, shellProblem } from './hookguard.js';

export const MANIFEST_FILE = 'piezas.manifest.json';
export const OUTSIDE_RECORD = 'outside-changes.json';
export const ALLOW_OUTSIDE = 'allow outside changes';
// Without a session id from the host (older hosts), an override lasts this long.
export const OUTSIDE_NO_SESSION_MS = 2 * 60 * 60 * 1000;

// --- texts -------------------------------------------------------------------

export const WORKSPACE_OWNER_TEXT =
  'Piezas apps normally change only their own folder. If Piezas is missing something, your AI tool tells you what is ' +
  'missing and the options instead of changing Piezas or other folders.';
export const SDK_OWNER_TEXT =
  'This would change the Piezas toolkit (@piezas/sdk) inside your app instead of using the published one. A changed copy ' +
  'can call parts of Piezas that do not exist, so things can break, and Piezas support can\'t help with that copy.';
export const OUTSIDE_CHOICE_TEXT =
  `If you, the owner, still want this for this session, type exactly: ${ALLOW_OUTSIDE} ` +
  '(until this session ends, it lets your AI tool change folders outside this app, Piezas\'s own tools in it, and the Piezas guardrails).';

export function outsideBlockReason(targets, root) {
  const list = targets.slice(0, 3).map((t) => `\`${t}\``).join(', ');
  return [
    WORKSPACE_OWNER_TEXT,
    OUTSIDE_CHOICE_TEXT,
    '',
    `(For the AI: paused because it writes outside this app's folder (${root}): ${list}. Contract Rule 11: if Piezas is ` +
      'missing something, tell the owner in plain words what is missing and the workable options, recommend one, and ' +
      'follow their choice. Change something outside the app only if the owner explicitly asked for it after you explained ' +
      'the risk; then show them the two sentences above. Never type the phrase yourself or treat "go ahead" as it: only ' +
      'the owner\'s own message counts. Reading files anywhere is fine.)',
  ].join('\n');
}

export function sdkBlockReason(detail) {
  return [
    SDK_OWNER_TEXT,
    'Recommended: keep the published toolkit and work around what is missing.',
    OUTSIDE_CHOICE_TEXT,
    '',
    `(For the AI: paused — ${detail}. Use the published SDK (\`npm install @piezas/sdk@latest\`, a plain version in ` +
      'package.json). Contract Rule 11: if the SDK lacks what the app needs, tell the owner in plain words what is missing ' +
      'and the options, recommend one, and follow their choice. Change, pack, link or vendor the toolkit only if the owner ' +
      'explicitly asked for it after you explained the risk and they typed the phrase themselves. A deploy with a changed ' +
      'toolkit pauses again and needs the owner\'s own "deploy anyway".)',
  ].join('\n');
}

// The manifest's link to the app: which app this project deploys to, the
// record of its earlier deploys, and its test copy (a key is minted for the
// app testApp names). Only the piezas commands write those fields (init,
// deploy, test --setup, the owner's "link to <name>"); the AI never does.
export const MANIFEST_LINK_BLOCK =
  'Piezas: which app this project deploys to (appName, deploy.appId, deploy.url and deploy.slug in piezas.manifest.json) ' +
  'and its test copy (testApp) are written only by the piezas commands, never by hand. Other fields are fine to edit, ' +
  'with the edit tools. To deploy to a different app, run the deploy with --app "<name>"; to replace an app another ' +
  'project put live, the owner replies "link to <app name>". The test copy is set up by `piezas test --setup`.';
const LINK_FIELDS = (m) => {
  const obj = (v) => (v && typeof v === 'object' ? v : {});
  const d = obj(m?.deploy);
  const t = obj(m?.testApp);
  return JSON.stringify([m?.appName ?? null, d.appId ?? null, d.url ?? null, d.slug ?? null, t.appId ?? null, t.appName ?? null]);
};
const IN_PLACE_EDIT = /\bsed\s+(?:-[a-z]*i|--in-place)|\bperl\s+-[a-z]*i/i;
// manifestLinkChanged — does the file the edit leaves change the link fields?
// A new manifest may name the app, never carry a deploy record. Text that does
// not parse keeps nothing (an unreadable manifest is no link at all), unless
// it still names those fields.
export function manifestLinkChanged(before, after) {
  if (typeof after !== 'string') return false;
  const parse = (t) => { try { const v = JSON.parse(String(t).replace(/^\uFEFF/, '')); return v && typeof v === 'object' ? v : null; } catch { return undefined; } };
  // A second "deploy" (or link) key, which one reader would take and another
  // skip, is a change too.
  const keys = (t) => (String(t ?? '').match(/"(?:appName|appId|url|slug|deploy|testApp)"\s*:/g) ?? []).length;
  if (keys(after) !== keys(before ?? '') && (before !== null || /"(?:appId|url|slug)"\s*:/.test(after))) return true;
  const next = parse(after);
  if (next === undefined) return /"(?:appId|url|slug|appName)"\s*:/.test(after);
  if (before === null) return LINK_FIELDS({}) !== LINK_FIELDS({ ...next, appName: null });
  const prev = parse(before);
  return LINK_FIELDS(prev ?? {}) !== LINK_FIELDS(next ?? {});
}
// manifestLinkShellWrite — a shell command that writes the manifest and names
// a link field, or replaces the whole file.
export function manifestLinkShellWrite(command) {
  const text = String(command || '');
  if (!/piezas\.manifest\.json/i.test(text)) return false;
  // An in-place edit can swap a link value without naming its field.
  if (IN_PLACE_EDIT.test(text)) return true;
  const writes = /(?:>|\btee\b|\bcp\b|\bmv\b|\bln\b|\binstall\b|\bdd\b|\btruncate\b|writeFile|write_text|\.write\(|open\([^)]*['"][wa]|\bsponge\b|\brsync\b)/i.test(text)
    || /(^|[\s;|&(])(node|python3?|ruby|perl|deno|bun)\s+(-e|-c|--eval)\b/.test(text);
  if (!writes) return false;
  if (/\b(?:cp|mv|ln|install|rsync)\b[^;|&\n]*piezas\.manifest\.json\s*(?:$|[;|&\n])/i.test(text)) return true;
  return /\b(?:appId|appName|url|slug|deploy|testApp)\b/.test(text);
}

