// --- the project root ------------------------------------------------------

const isProjectDir = (dir) => existsSync(join(dir, MANIFEST_FILE)) || existsSync(join(dir, STATE_DIR, 'state.json'));

// projectAt — the nearest folder at or above dir that is a Piezas project, or null.
export function projectAt(dir) {
  let d = resolve(dir);
  for (;;) {
    if (isProjectDir(d)) return d;
    const parent = dirname(d);
    if (parent === d) return null;
    d = parent;
  }
}

// workspaceRoot — the Piezas project a session works in: the nearest folder at
// or above cwd with piezas.manifest.json (or .piezas/state.json); otherwise the
// only such folder one or two levels below cwd (a session opened in the folder
// that holds the app). null when this is not a Piezas session. The folder
// below is a guess, good for finding the app and recording the owner's
// replies; the guard never refuses a write on that guess (workspaceVerdict).
export function workspaceRoot(cwd) {
  const here = resolve(cwd || process.cwd());
  const inside = projectAt(here);
  if (inside) return inside;
  const below = childProjects(here, 2, isProjectDir);
  return below.length === 1 ? below[0] : null;
}

// ownerReplyRoot — where the owner's typed replies ("deploy anyway", ...) are
// recorded: the session's project, also when it has only a manifest or only a
// waiting deploy pause (.piezas/deploy-confirm.json), no protocol state.
export function ownerReplyRoot(cwd) {
  let d = resolve(cwd || process.cwd());
  for (;;) {
    if (isProjectDir(d) || existsSync(join(d, STATE_DIR, DEPLOY_RISK_FILE))) return d;
    const parent = dirname(d);
    if (parent === d) break;
    d = parent;
  }
  return workspaceRoot(cwd);
}

// realish — the real path of p, through the deepest part that exists (macOS
// /var -> /private/var, symlinked temp folders), so "inside" compares like
// with like even for files not created yet.
export function realish(p) {
  let head = resolve(p);
  const tail = [];
  for (;;) {
    try {
      const real = realpathSync(head);
      return tail.length ? join(real, ...tail.reverse()) : real;
    } catch {
      const parent = dirname(head);
      if (parent === head) return resolve(p);
      tail.push(basename(head));
      head = parent;
    }
  }
}

export function isInside(child, parent) {
  const rel = relative(parent, child);
  return rel === '' || (!!rel && !rel.startsWith('..') && !isAbsolute(rel));
}

// Folders always open for writing: the OS temp folder (and /tmp), the devices,
// and Claude Code's own plan and memory notes. PIEZAS_TEMP_DIR replaces the
// temp list (tests use it: their projects themselves live in the temp folder).
export function openWriteDirs(env = process.env) {
  const temps = env.PIEZAS_TEMP_DIR
    ? String(env.PIEZAS_TEMP_DIR).split(':').filter(Boolean)
    : [tmpdir(), env.TMPDIR, '/tmp', '/private/tmp', '/var/tmp'].filter(Boolean);
  const home = env.HOME || homedir();
  const dirs = [...temps, '/dev', join(home, '.claude', 'plans')];
  return [...new Set(dirs.map((d) => realish(d)))];
}

function isClaudeMemory(real, env) {
  const home = realish(env.HOME || homedir());
  const rel = relative(join(home, '.claude', 'projects'), real);
  return !!rel && !rel.startsWith('..') && !isAbsolute(rel) && rel.split(sep)[1] === 'memory';
}

// --- Piezas's own packages, inside the project -----------------------------

const PIEZAS_PACKAGE_PATH = [
  /(^|\/)node_modules\/@piezas(\/|$)/,
  // The Piezas CLI the project's own hooks run, and the hook file itself
  // (written by `piezas init`): changing either switches the checks off.
  /(^|\/)node_modules\/piezas(\/|$)/,
  /^\.piezas\/hooks(\/|$)/,
  /(^|\/)@piezas(\/|$)/,
  /(^|\/)vendor\/[^/]*piezas/i,
  /piezas-sdk[^/]*\.(?:tgz|tar\.gz|tar)$/i,
];

export function isPiezasPackagePath(relPosix) {
  return PIEZAS_PACKAGE_PATH.some((re) => re.test(relPosix));
}

// piezasSpecProblem — why a dependency spec for an @piezas/* package is not
// the published one, or null when it is a plain registry version or range.
export function piezasSpecProblem(spec) {
  const s = String(spec ?? '').trim();
  if (!s) return 'has no version';
  if (/^(?:file|link|workspace|portal|patch|npm|git(?:\+[a-z]+)?|github|gitlab|bitbucket|gist|https?):/i.test(s) || /^git@/.test(s)) {
    return `points at ${s} instead of the published version`;
  }
  if (/^(?:\.\.?(?:\/|$)|\/|~\/)/.test(s) || /\.(?:tgz|tar\.gz|tar)$/i.test(s) || /^[\w.-]+\/[\w.-]+(?:#.*)?$/.test(s)) {
    return `points at ${s} instead of the published version`;
  }
  if (s === 'latest' || s === '*' || s === 'x') return null;
  if (/\d+\.\d+\.\d+-[0-9A-Za-z.-]+/.test(s)) return `is a pre-release build (${s}), not a published version`;
  if (/^[\s\d.xX*^~<>=|-]+$/.test(s)) return null;
  return `uses "${s}", which is not a published version number`;
}

const DEP_FIELDS = ['dependencies', 'devDependencies', 'optionalDependencies', 'peerDependencies'];

// piezasDependencyProblems — every @piezas/* dependency in a package.json
// object that is not a published version: [{ name, spec, problem, field }].
// The overrides are read the same way the Piezas MCP reads them from a build
// (provenance.go overrideProblems): npm `overrides`, yarn `resolutions` and
// `pnpm.overrides`, every one of them. The rule for a value:
//   - a string is the version the override sets;
//   - an object (npm's nested form) sets its own "." string, and its other
//     keys are overrides inside it, read the same way;
//   - a string starting with "$" is npm's reference to the app's own
//     dependency (checked there), so it is skipped;
//   - anything else (a number, a list, null, an object without a "." string)
//     sets no version and is skipped.
// A key overrides an @piezas package when the text after its LAST "@piezas/"
// names one package (an "@<version>" selector after it is allowed, a "/" or
// ">" is not): "@piezas/sdk", "**/@piezas/sdk", "parent>@piezas/sdk",
// "@piezas/sdk@^1". The finding's name is the key exactly as written.
export function piezasDependencyProblems(pkg) {
  const out = [];
  if (!pkg || typeof pkg !== 'object' || Array.isArray(pkg)) return out;
  for (const field of DEP_FIELDS) {
    const deps = pkg[field];
    if (!deps || typeof deps !== 'object') continue;
    for (const [name, spec] of Object.entries(deps)) {
      if (!name.startsWith('@piezas/')) continue;
      const problem = piezasSpecProblem(typeof spec === 'string' ? spec : '');
      if (problem) out.push({ name, spec: String(spec), problem, field });
    }
  }
  const pnpm = pkg.pnpm && typeof pkg.pnpm === 'object' ? pkg.pnpm : {};
  for (const [field, section] of [['overrides', pkg.overrides], ['resolutions', pkg.resolutions], ['pnpm.overrides', pnpm.overrides]]) {
    out.push(...overrideProblems(section, field));
  }
  return out;
}

// overrideTarget — the @piezas package an override key replaces, or null.
export function overrideTarget(key) {
  const i = String(key).lastIndexOf('@piezas/');
  if (i < 0) return null;
  let rest = String(key).slice(i + '@piezas/'.length);
  const at = rest.indexOf('@');
  if (at >= 0) rest = rest.slice(0, at);
  if (!rest || /[/>]/.test(rest)) return null;
  return `@piezas/${rest}`;
}

function overrideProblems(section, field) {
  const out = [];
  if (!section || typeof section !== 'object' || Array.isArray(section)) return out;
  for (const key of Object.keys(section).sort()) {
    const value = section[key];
    const isObj = value && typeof value === 'object' && !Array.isArray(value);
    if (overrideTarget(key)) {
      const spec = isObj ? value['.'] : value;
      if (typeof spec === 'string' && !spec.trim().startsWith('$')) {
        const problem = piezasSpecProblem(spec);
        if (problem) out.push({ name: key, spec, problem, field });
      }
    }
    if (isObj) out.push(...overrideProblems(value, field));
  }
  return out;
}

// isPublishedLinkTarget — a symlinked node_modules/@piezas/<name> that points
// at a package manager's own copy of a published version: pnpm links every
// direct dependency into node_modules/.pnpm/@piezas+<name>@<version>/...
// (a file:, link:, git or tarball install there is named file+..., link+...,
// git..., https+...). Anything else is a local folder (npm link).
export function isPublishedLinkTarget(target) {
  const m = /(?:^|\/)node_modules\/\.pnpm\/([^/]+)\/node_modules\/@piezas\/[^/]+\/?$/.exec(String(target).split(sep).join('/'));
  return !!m && /^@piezas\+[^@/]+@\d/.test(m[1]) && !/(?:file|link|git|github|https?)\+|\.(?:tgz|tar)/i.test(m[1]);
}

// readPackageJson — a package.json as an object: { pkg } when it reads, {
// missing } when there is none, { unreadable } when it is there but cannot be
// read or is not a JSON object (a leading UTF-8 BOM is allowed, as npm does).
function readPackageJson(file) {
  let raw;
  try { raw = readFileSync(file, 'utf-8'); } catch (err) { return err?.code === 'ENOENT' || err?.code === 'ENOTDIR' ? { missing: true } : { unreadable: true }; }
  try {
    const pkg = JSON.parse(raw.replace(/^﻿/, ''));
    return pkg && typeof pkg === 'object' && !Array.isArray(pkg) ? { pkg } : { unreadable: true };
  } catch {
    return { unreadable: true };
  }
}

// installedSdkProblems — what the INSTALLED copies say about where they came
// from, for every node_modules/@piezas/<dir>: a symlink to a local folder (npm
// link), a package.json that cannot be read, an old npm's `_resolved` that is
// not a web address, a pre-release or missing version; and the lock file's
// entries resolved from a file/link/git. The finding's name is always
// "@piezas/<dir>" (the folder, never what the copy's own package.json claims).
export function installedSdkProblems(projectDir) {
  const out = [];
  const dir = resolve(projectDir);
  const scope = join(dir, 'node_modules', '@piezas');
  let entries = [];
  try { entries = readdirSync(scope).sort(); } catch { /* none installed */ }
  for (const entry of entries) {
    const name = `@piezas/${entry}`;
    const rel = `node_modules/@piezas/${entry}`;
    const installed = join(scope, entry);
    try {
      if (lstatSync(installed).isSymbolicLink()) {
        // The link as written (relative links still read right in a copied
        // folder, where the target may not exist), then where it really ends.
        const written = resolve(dirname(installed), readlinkSync(installed));
        let real = null;
        try { real = realpathSync(installed); } catch { /* dangling */ }
        if (!isPublishedLinkTarget(written) && !(real && isPublishedLinkTarget(real))) {
          out.push({ name, problem: 'is linked to a local folder (npm link), not installed from npm', where: rel, source: written });
        }
      }
    } catch { /* gone */ }
    const read = readPackageJson(join(installed, 'package.json'));
    if (read.missing) continue;
    if (read.unreadable) {
      out.push({ name: `${rel}/package.json`, problem: 'unreadable', where: 'unreadable', file: `${rel}/package.json` });
      continue;
    }
    const pkg = read.pkg;
    if (typeof pkg._resolved === 'string' && pkg._resolved.trim() && !/^https?:\/\//i.test(pkg._resolved.trim())) {
      out.push({ name, problem: `was installed from ${pkg._resolved}`, where: `${rel}/package.json`, source: pkg._resolved.trim() });
    }
    if (typeof pkg.version !== 'string' || !pkg.version) {
      out.push({ name, problem: 'has no version, so it is not a published one', where: `${rel}/package.json` });
    } else if (/-/.test(pkg.version)) {
      out.push({ name, problem: `is a pre-release build (${pkg.version}), not a published version`, where: `${rel}/package.json`, source: pkg.version });
    }
  }
  try {
    const lock = JSON.parse(readFileSync(join(dir, 'package-lock.json'), 'utf-8'));
    for (const key of Object.keys(lock.packages || {}).sort()) {
      const entry = lock.packages[key];
      if (!/(^|\/)node_modules\/@piezas\/[^/]+$/.test(key) || !entry || typeof entry !== 'object') continue;
      const name = key.slice(key.lastIndexOf('@piezas/'));
      if (entry.link) out.push({ name, problem: `is linked to ${entry.resolved || 'a local folder'}, not installed from npm`, where: 'package-lock.json', ...(entry.resolved ? { source: String(entry.resolved) } : {}) });
      else if (typeof entry.resolved === 'string' && !/^https?:\/\//.test(entry.resolved)) {
        out.push({ name, problem: `was installed from ${entry.resolved}`, where: 'package-lock.json', source: entry.resolved });
      }
    }
  } catch { /* no lock */ }
  return out;
}

// sdkProvenance — the project's verdict, for doctor (PZ028) and deploy. A
// package.json that is there but cannot be read is one finding (name
// "package.json", where "unreadable"): a broken file can still name a
// homemade copy that a looser reader would install.
export function sdkProvenance(projectDir) {
  const read = readPackageJson(join(resolve(projectDir), 'package.json'));
  const declared = read.unreadable
    ? [{ name: 'package.json', problem: 'unreadable', where: 'unreadable', file: 'package.json' }]
    : piezasDependencyProblems(read.pkg).map((p) => ({ ...p, where: 'package.json' }));
  const installed = installedSdkProblems(projectDir);
  return { ok: declared.length === 0 && installed.length === 0, problems: [...declared, ...installed] };
}

export function sdkProvenanceLines(problems) {
  return problems.map((p) => (p.where === 'unreadable' ? `${p.name} unreadable` : `${p.name} ${p.problem} (${p.where})`));
}

// sdkKeyLines — the toolkit copy's answer-key lines: "name NUL where" for each
// finding, unique and sorted (code-unit order, as Go's sort.Strings). The
// Piezas MCP derives the same lines from the build it receives.
export function sdkKeyLines(problems) {
  return [...new Set(problems.map((p) => `${p.name}\u0000${p.where}`))].sort();
}

// sdkPauseKey — sha256 of the key lines joined by "\n", first 24 hex.
export function sdkPauseKey(problems) {
  return createHash('sha256').update(sdkKeyLines(problems).join('\n')).digest('hex').slice(0, 24);
}

// sdkProjectKeyLines — when only the project shows a copy (the build carries
// no evidence: static builds, often standalone ones), the key comes from the
// project's own evidence: the same "name NUL where" lines, each followed by
// NUL and where that copy came from (the package.json spec, the lock file's or
// the installed copy's resolved source, a link's target), as a path relative
// to the project or a web address. So it is never a constant, and a different
// copy is a different answer key. The Piezas MCP sees only the build and
// cannot derive these: it asks the owner again in that case.
export function sdkProjectKeyLines(problems, projectDir) {
  const where = (src) => {
    let s = String(src ?? '').trim();
    if (!s) return '';
    const local = /^(?:file|link):(.*)$/.exec(s);
    const path = local ? local[1] : s;
    if (isAbsolute(path) && projectDir) {
      const rel = relative(resolve(projectDir), path).split(sep).join('/') || '.';
      s = local ? `${s.slice(0, s.indexOf(':') + 1)}${rel}` : rel;
    }
    return s;
  };
  return [...new Set(problems.map((p) => `${p.name}\u0000${p.where}\u0000${where(p.source ?? p.spec)}`))].sort();
}

export function sdkProjectPauseKey(problems, projectDir) {
  return createHash('sha256').update(sdkProjectKeyLines(problems, projectDir).join('\n')).digest('hex').slice(0, 24);
}

// The owner-facing pause a deploy prints; same words on the hosting side.
export const UNPUBLISHED_SDK_OWNER_TEXT =
  'This app uses its own copy of the Piezas toolkit instead of the published one. Parts of Piezas it calls may not ' +
  'exist, so things can break, and Piezas support can\'t help with that copy. Recommended: your AI tool switches the ' +
  'app back to the published toolkit and builds it again.';

// --- the owner's override ----------------------------------------------------

export function readOutsideOverride(root) {
  try {
    return JSON.parse(readFileSync(join(root, STATE_DIR, OUTSIDE_RECORD), 'utf-8'));
  } catch {
    return null;
  }
}

export function outsideAllowed(root, sessionId, now = Date.now()) {
  const record = readOutsideOverride(root);
  if (!record || record.by !== 'owner' || record.via !== 'user-prompt') return false;
  if (record.sessionId || sessionId) return !!record.sessionId && record.sessionId === sessionId;
  const age = now - Date.parse(record.at);
  return Number.isFinite(age) && age >= 0 && age < OUTSIDE_NO_SESSION_MS;
}

export function isAllowOutsidePrompt(prompt) {
  const said = String(prompt || '').trim().toLowerCase().replace(/[’"']/g, '').replace(/[.!]+$/, '').replace(/\s+/g, ' ');
  return said === ALLOW_OUTSIDE || said === '/piezas:allow-outside-changes' || said === '/allow-outside-changes';
}

// recordOutsideOverride — called by the UserPromptSubmit hook with the owner's
// own message. Returns a note for the session, or '' when the message is not
// the phrase.
export function recordOutsideOverride(root, payload) {
  if (!root || !isAllowOutsidePrompt(payload?.prompt)) return '';
  const sessionId = typeof payload.session_id === 'string' && payload.session_id ? payload.session_id : null;
  mkdirSync(join(root, STATE_DIR), { recursive: true });
  writeFileSync(
    join(root, STATE_DIR, OUTSIDE_RECORD),
    `${JSON.stringify({ allow: 'outside-changes', by: 'owner', via: 'user-prompt', sessionId, said: String(payload.prompt).trim().slice(0, 80), at: new Date().toISOString() }, null, 2)}\n`,
  );
  return 'The owner typed "allow outside changes" themselves, and it is recorded: for the rest of this session only, you may ' +
    'make the change they asked for outside the app\'s folder, or to the Piezas toolkit copy inside the project. Make only ' +
    'that change. Tell them in one sentence that it is allowed until this session ends, and remind them in plain words that ' +
    'a changed Piezas toolkit can break and Piezas support can\'t help with it, and that going live with one asks them again.';
}

// --- shell commands ------------------------------------------------------------

// tokenizeShell — a small, forgiving shell lexer: simple commands split on
// ; && || | & newlines and parentheses, quotes honored, with each redirect
// target collected separately. A word holding $(...), `...` or an unknown $VAR
// is kept with a `dynamic` flag so callers can skip it. Heredoc bodies must be
// stripped first.
export function tokenizeShell(command) {
  const text = String(command || '');
  const commands = [];
  let words = [];
  let redirects = [];
  let word = null;
  let dynamic = false;
  let mode = null; // 'redirect' | 'skip' — what the next word is
  const endWord = () => {
    if (word === null) return;
    const w = { text: word, dynamic };
    if (mode === 'redirect') redirects.push(w);
    else if (mode !== 'skip') words.push(w);
    mode = null;
    word = null;
    dynamic = false;
  };
  const endCommand = () => {
    endWord();
    if (words.length || redirects.length) commands.push({ words, redirects });
    words = [];
    redirects = [];
    mode = null;
  };
  for (let i = 0; i < text.length; i += 1) {
    const c = text[i];
    if (c === '\\') {
      if (text[i + 1] === '\n') { i += 1; continue; }
      word = (word ?? '') + (text[i + 1] ?? '');
      i += 1;
      continue;
    }
    if (c === "'") {
      const end = text.indexOf("'", i + 1);
      const stop = end < 0 ? text.length : end;
      word = (word ?? '') + text.slice(i + 1, stop);
      i = stop;
      continue;
    }
    if (c === '"') {
      let j = i + 1;
      let buf = '';
      while (j < text.length && text[j] !== '"') {
        if (text[j] === '\\' && j + 1 < text.length && '"\\$`'.includes(text[j + 1])) { buf += text[j + 1]; j += 2; continue; }
        if (text[j] === '`' || (text[j] === '$' && text[j + 1] === '(')) dynamic = true;
        buf += text[j];
        j += 1;
      }
      word = (word ?? '') + buf;
      i = j;
      continue;
    }
    if (c === '#' && word === null) {
      const nl = text.indexOf('\n', i);
      i = nl < 0 ? text.length : nl - 1;
      continue;
    }
    if (c === ' ' || c === '\t') { endWord(); continue; }
    if (c === '\n' || c === ';' || c === '(' || c === ')') { endCommand(); continue; }
    if (c === '|' || c === '&') {
      if (c === '&' && text[i + 1] === '>') { // &> file
        endWord();
        i += text[i + 2] === '>' ? 2 : 1;
        mode = 'redirect';
        continue;
      }
      endCommand();
      if (text[i + 1] === c) i += 1;
      continue;
    }
    if (c === '>') {
      // "2>" / "1>>": the digits belong to the redirect, not to the command.
      if (word !== null && /^\d+$/.test(word)) { word = null; dynamic = false; }
      endWord();
      if (text[i + 1] === '>' || text[i + 1] === '|') i += 1;
      if (text[i + 1] === '&') { // >&2, >&-
        i += 1;
        mode = 'skip';
        continue;
      }
      mode = 'redirect';
      continue;
    }
    if (c === '<') {
      endWord();
      while (text[i + 1] === '<') i += 1;
      if (text[i + 1] === '(') { endCommand(); continue; } // <(process substitution)
      mode = 'skip';
      continue;
    }
    if (c === '`' || (c === '$' && text[i + 1] === '(')) dynamic = true;
    word = (word ?? '') + c;
  }
  endCommand();
  return commands;
}

// expandWord — the literal path a word stands for, or null when it depends on
// something the guard cannot know (command output, an unknown variable).
export function expandWord(w, ctx) {
  if (!w || w.dynamic) return null;
  let s = w.text;
  const home = ctx.env.HOME || homedir();
  if ((s === '~+' || s.startsWith('~+/')) && ctx.cwd) s = ctx.cwd + s.slice(2);
  else if (s === '~' || s.startsWith('~/')) s = home + s.slice(1);
  let unknown = false;
  s = s.replace(/\$\{?([A-Za-z_][A-Za-z0-9_]*)\}?/g, (m, name) => {
    if (name === 'HOME') return home;
    if (name === 'PWD' && ctx.cwd) return ctx.cwd;
    if (name === 'TMPDIR') return ctx.env.TMPDIR || tmpdir();
    if (name === 'CLAUDE_PROJECT_DIR' && ctx.env.CLAUDE_PROJECT_DIR) return ctx.env.CLAUDE_PROJECT_DIR;
    unknown = true;
    return m;
  });
  return unknown ? null : s;
}

const WRAPPERS = new Set(['sudo', 'command', 'exec', 'time', 'nohup', 'nice', 'builtin', 'doas']);
const GIT_WRITES = new Set([
  'add', 'am', 'apply', 'branch', 'checkout', 'cherry-pick', 'clean', 'clone', 'commit', 'init', 'merge', 'mv', 'pull',
  'push', 'rebase', 'reset', 'restore', 'revert', 'rm', 'stash', 'switch', 'tag', 'worktree',
]);
const PM = new Set(['npm', 'pnpm', 'yarn', 'bun']);
const PM_READ_ONLY = new Set(['view', 'info', 'show', 'ls', 'list', 'outdated', 'whoami', 'help', 'search', 'why', 'explain', 'config', 'get', 'root', 'bin', 'prefix', 'doctor', 'ping', 'test', 't', 'audit']);
const PM_INSTALL = new Set(['install', 'i', 'add', 'isntall', 'in', 'ins', 'inst', 'insta', 'instal', 'update', 'up', 'upgrade', 'ci']);
const PM_OPTS_WITH_VALUE = new Set(['--prefix', '-C', '--dir', '--cwd', '-w', '--workspace', '--filter', '-F', '--registry', '--tag', '--cache']);
const OUTSIDE_RUNNERS = new Set(['npx', 'pnpx', 'bunx', 'make', 'cargo', 'patch', 'gofmt', 'goimports']);
const GO_WRITES = new Set(['build', 'generate', 'get', 'install', 'mod', 'fmt', 'work', 'fix']);

function isOption(t) {
  return typeof t === 'string' && t.startsWith('-') && t !== '-';
}

// pathish — an install argument that is a file, folder, tarball or URL, not a
// registry package name.
function pathish(arg) {
  return /^(?:file|link|workspace|portal|git(?:\+[a-z]+)?|github|gitlab|bitbucket|https?):/i.test(arg) || /^git@/.test(arg) ||
    /^(?:\.\.?(?:\/|$)|\/|~\/)/.test(arg) || /\.(?:tgz|tar\.gz|tar)$/i.test(arg) || /^[\w.-]+\/[\w.-]+(?:#.*)?$/.test(arg);
}

function packageNameAt(dir) {
  if (!dir) return '';
  try {
    return String(JSON.parse(readFileSync(join(dir, 'package.json'), 'utf-8')).name || '');
  } catch {
    return '';
  }
}

// isPiezasPackageRef — does an install/link/pack argument stand for a Piezas
// package (by name, by path to its folder, or by a piezas-named tarball)?
function isPiezasPackageRef(arg, cwd) {
  if (/piezas/i.test(arg)) return true;
  const local = arg.replace(/^(?:file|link):/i, '');
  if (cwd && /^[.~/]|^[\w.-]+$/.test(local)) {
    const abs = resolve(cwd, local);
    if (packageNameAt(abs).startsWith('@piezas/')) return true;
  }
  return false;
}

const GLOB = /[*?[\]{]/;

// globToRegExp — a shell pattern (one path part) as a RegExp. Leading dots
// match too: the guard errs toward "this could land there".
function globToRegExp(pattern) {
  let re = '';
  for (const c of pattern) {
    if (c === '*') re += '.*';
    else if (c === '?') re += '.';
    else if (c === '[' || c === ']') re += c;
    else re += c.replace(/[.+^${}()|\\]/g, '\\$&');
  }
  try { return new RegExp(`^${re}$`); } catch { return /^.*$/; }
}

function listDir(dir) {
  try { return readdirSync(dir); } catch { return null; }
}

// copyTargets — the paths a copy of source into the existing folder destDir
// writes. A folder source with a trailing slash ("dir/", "dir/."), and a
// pattern ("dir/*"), drop their CONTENTS straight into destDir, so each entry
// is a target; when the guard cannot list them, destDir/* stands for them.
function copyTargets(source, sourceAbs, destDir) {
  if (source === null || source === undefined) return [join(destDir, '*')];
  const contents = /\/\.?$/.test(source);
  const name = basename(source);
  if (GLOB.test(name)) {
    const entries = sourceAbs ? listDir(dirname(sourceAbs)) : null;
    if (!entries) return [join(destDir, '*')];
    const re = globToRegExp(name);
    return entries.filter((e) => re.test(e)).map((e) => join(destDir, e));
  }
  if (contents) {
    const entries = sourceAbs ? listDir(sourceAbs) : null;
    return entries ? entries.map((e) => join(destDir, e)) : [join(destDir, '*')];
  }
  return [join(destDir, name)];
}

// --- scripts passed inline (node -e, python -c, ruby -e, perl -e, bun -e) ---

// The calls that write, in the languages an AI runs inline.
const SCRIPT_WRITES = new RegExp([
  // Node / Bun / Deno
  String.raw`\b(?:writeFile|appendFile|createWriteStream|copyFile|cpSync|cp|rename|renameSync|symlink|symlinkSync|link|linkSync|mkdir|mkdirSync|rmSync|rm|rmdir|rmdirSync|unlink|unlinkSync|truncate|truncateSync|writeSync|outputFile|copy|move|ensureDir)\s*\(`,
  String.raw`\b(?:writeFileSync|appendFileSync|copyFileSync)\b`, String.raw`\bopen(?:Sync)?\s*\([^)]*['"][wax+]`, String.raw`Bun\.write`, String.raw`Deno\.(?:write|copy|rename|mkdir|remove|symlink|link)`,
  String.raw`\b(?:exec|execSync|execFile|execFileSync|spawn|spawnSync|fork)\s*\(`, String.raw`\bchild_process\b`,
  // Python
  String.raw`\bshutil\.`, String.raw`\bos\.(?:rename|replace|link|symlink|makedirs|mkdir|remove|unlink|rmdir|system|popen|write)\b`, String.raw`\bsubprocess\.`,
  String.raw`\bopen\s*\([^)]*,\s*['"][^'"]*[wax+]`, String.raw`\.(?:write_text|write_bytes|touch|symlink_to|hardlink_to)\s*\(`, String.raw`\bPath\s*\([^)]*\)\s*\.(?:rename|replace|mkdir)\s*\(`,
  // Ruby / Perl
  String.raw`\bFile\.(?:write|open|rename|symlink|link)\b`, String.raw`\bFileUtils\.`, String.raw`\bIO\.write\b`, String.raw`\bsystem\s*\(`,
  String.raw`\bopen\s*\(?\s*(?:my\s+)?\$?\w*\s*,\s*['"][+>]`, String.raw`\bopen\s*\(?[^,)]*,\s*['"]?>`,
].join('|'));

// A copy-like call with two literal paths: fs.cpSync(src, dest), shutil.copytree(src, dest), ...
const SCRIPT_COPY = /\b(?:cpSync|cp|copyFileSync|copyFile|renameSync|rename|copy|copy2|copyfile|copytree|move|replace|cp_r|mv|ln_s|ln|symlinkSync|symlink)\s*\(\s*(['"`])([^'"`]+)\1\s*,\s*(['"`])([^'"`]+)\3/g;
// Shell text run from the script: exec('cp ...'), os.system("..."), subprocess.run("...", shell=True), system("...").
const SCRIPT_SHELL = /\b(?:exec|execSync|system|popen|run|call|check_call|check_output|getoutput|Popen|spawnSync|spawn)\s*\(\s*(['"`])([^'"`]+)\1/g;
// An argv list: spawn('cp', ['-R', 'a', 'b']), subprocess.run(['cp', 'a', 'b']).
const SCRIPT_ARGV = /\b(?:spawn|spawnSync|execFile|execFileSync|run|call|check_call|check_output|Popen)\s*\(\s*(?:(['"])([^'"]+)\1\s*,\s*)?\[([^\]]*)\]/g;
// .piezas as a quoted path or a path part ('.piezas', './.piezas/', 'x/.piezas/y', path.join(root, '.piezas')).
const PIEZAS_MENTION = /(['"`])((?:[^'"`\n]*\/)?\.piezas(?:\/[^'"`\n]*)?)\1/g;
// Words that, in an inline script that writes, mean the owner's records, the
// quality scan's files or the guardrails (a name split in two still has one half).
// Actual record paths only, never bare substrings ("copies.txt", "recipes",
// "quality-report.csv" are the app's own files): a .piezas path segment, or a
// record's file name. Quoted pieces joined with + are read as one string
// first, so '.pie' + 'zas/state.json' still counts. (The guardrails' own
// files are the hooks guard's: hookguard.js.)
const OWNER_RECORD_PATH = /(?:^|[\s'"`/\\(=,])\.piezas(?:$|[\s'"`/\\),;])|owner-approvals\.json|(?:^|[\s'"`/\\(=,])state\.json|quality-attestation\.json|scan-state\.json|outside-changes\.json|deploy-confirm\.json|test-attestation\.json|test-decisions\.json|import\.json/i;
function namesOwnerRecord(code) {
  const joined = String(code).replace(/(['"`])\s*\+\s*(['"`])/g, '');
  return OWNER_RECORD_PATH.test(joined.replace(/\.piezas\/(?:dev\.log|test-results[^'"`\s]*)/g, ''));
}
// What the AI itself keeps in .piezas: the dev server log, the test results.
const AI_OWNED_IN_STATE = /^(?:\.\/)?\.piezas\/(?:dev\.log|test-results(?:\/[^'"`]*)?)$/;

export function scriptCode(args, texts, name) {
  const flags = name === 'python' || name === 'python3' ? ['-c'] : name === 'deno' ? ['eval'] : ['-e', '-E', '--eval', '-p', '--print'];
  const at = texts.findIndex((t) => typeof t === 'string' && flags.includes(t));
  if (at < 0) return null;
  const code = args[at + 1]?.raw.text;
  return typeof code === 'string' ? code : null;
}

// analyzeShell — what a shell command would write, with the working folder
// tracked through cd/pushd. Returns { writes: [abs] (created or changed),
// deletes: [abs], mkdirs: [abs] (folders made, or only given new entries),
// outsideCwd: [abs dirs a writer ran in],
// sdk: [reasons] }.
export function analyzeShell(command, cwd, env = process.env, depth = 0) {
  const result = { writes: [], deletes: [], mkdirs: [], outsideCwd: [], sdk: [], unknown: 0, scripted: false };
  const ctx = { cwd: cwd ? resolve(cwd) : null, env };
  const at = (p) => {
    if (p === null || p === undefined || p === '') return null;
    if (/^\/dev\//.test(p) || p === '/dev/null') return null;
    if (isAbsolute(p)) return resolve(p);
    return ctx.cwd ? resolve(ctx.cwd, p) : null;
  };
  // A target the guard cannot work out ($VAR, command output) is counted.
  const write = (p) => {
    const abs = at(p);
    if (abs) result.writes.push(abs);
    else if (p === null) result.unknown += 1;
  };
  const remove = (p) => {
    const abs = at(p);
    if (abs) result.deletes.push(abs);
    else if (p === null) result.unknown += 1;
  };
  const merge = (inner) => {
    for (const k of Object.keys(result)) {
      if (Array.isArray(result[k])) result[k].push(...inner[k]);
    }
    result.unknown += inner.unknown;
    result.scripted = result.scripted || inner.scripted;
  };
  const writeText = (p) => write(expandWord({ text: p, dynamic: false }, ctx));
  // A script passed inline that writes (node -e, python -c, ruby -e, perl -e,
  // bun -e, deno eval): what it names is checked like a shell command's.
  const inlineScript = (name, args, texts) => {
    const code = scriptCode(args, texts, name);
    if (!code || !SCRIPT_WRITES.test(code)) return;
    result.scripted = true;
    // 0. It names the owner's records or the guardrails, even split in two
    //    ('.pie' + 'zas'): it counts as writing the records folder.
    if (namesOwnerRecord(code) && ctx.cwd) {
      const project = projectAt(ctx.cwd);
      if (project) result.writes.push(join(project, STATE_DIR));
    }
    // 1. It names .piezas: that folder holds the owner's records, so the
    //    script counts as writing the folder (the AI's own log and test
    //    results excepted). A script that only reads it never gets here.
    for (const m of code.matchAll(PIEZAS_MENTION)) {
      const quoted = m[2];
      if (AI_OWNED_IN_STATE.test(quoted)) { writeText(quoted); continue; }
      const base = quoted.slice(0, quoted.indexOf('.piezas') + '.piezas'.length);
      if (/^(?:\.{1,2}\/|\/|~\/)/.test(base) || base.includes('/')) writeText(base);
      else if (ctx.cwd) {
        // Only the folder's name (path.join(root, '.piezas')): the project's own.
        const project = projectAt(ctx.cwd);
        result.writes.push(join(project ?? ctx.cwd, STATE_DIR));
      }
    }
    // 2. A copy with literal paths: into an existing folder, what lands there
    //    (a folder's contents too, as fs.cpSync and shutil.copytree copy them).
    for (const m of code.matchAll(SCRIPT_COPY)) {
      const src = m[2];
      const dest = m[4];
      const srcAbs = at(expandWord({ text: src, dynamic: false }, ctx));
      const destAbs = at(expandWord({ text: dest, dynamic: false }, ctx));
      if (!destAbs) continue;
      const srcIsDir = !!srcAbs && safeIsDir(srcAbs);
      const contents = srcIsDir ? copyTargets(`${src.replace(/\/+$/, '')}/`, srcAbs, destAbs) : [];
      if (safeIsDir(destAbs) || /\/\.?$/.test(dest)) {
        for (const t of [...contents, ...copyTargets(src, srcAbs, destAbs)]) write(t);
      } else {
        write(destAbs);
        for (const t of contents) write(t);
      }
    }
    // 3. Shell text it runs (exec('cp ...'), os.system(...), subprocess.run([...])).
    if (depth < 3) {
      for (const m of code.matchAll(SCRIPT_SHELL)) merge(analyzeShell(m[2], ctx.cwd, env, depth + 1));
      for (const m of code.matchAll(SCRIPT_ARGV)) {
        const argv = [m[2], ...[...m[3].matchAll(/(['"])([^'"]*)\1/g)].map((x) => x[2])].filter((x) => typeof x === 'string' && x);
        if (argv.length) merge(analyzeShell(argv.map((a) => `'${a.replace(/'/g, "'\\''")}'`).join(' '), ctx.cwd, env, depth + 1));
      }
    }
    // 4. Every quoted path it names.
    for (const m of code.matchAll(/['"`]((?:\.{1,2}\/|\/|~\/)[^'"`\s]+)['"`]/g)) writeText(m[1]);
  };
  for (const { words: rawWords, redirects } of tokenizeShell(command)) {
    for (const r of redirects) write(expandWord(r, ctx));
    let ws = rawWords.map((w) => ({ raw: w, text: expandWord(w, ctx) }));
    // Leading VAR=value assignments and wrappers (sudo, env, nohup, ...).
    for (;;) {
      const first = ws[0];
      if (!first) break;
      const t = first.raw.text;
      if (/^[A-Za-z_][A-Za-z0-9_]*=/.test(t)) { ws = ws.slice(1); continue; }
      if (WRAPPERS.has(t) || t === 'env') {
        ws = ws.slice(1);
        while (ws[0] && (isOption(ws[0].raw.text) || (t === 'env' && /^[A-Za-z_][A-Za-z0-9_]*=/.test(ws[0].raw.text)))) ws = ws.slice(1);
        continue;
      }
      break;
    }
    if (!ws.length) continue;
    const name = basename(ws[0].raw.text);
    const args = ws.slice(1);
    const texts = args.map((a) => a.text);
    const operands = args.filter((a) => !isOption(a.raw.text));

    if (name === 'cd' || name === 'pushd') {
      const target = operands[0];
      if (!target) ctx.cwd = resolve(env.HOME || homedir());
      else if (target.text === null || target.raw.text === '-') ctx.cwd = null;
      else ctx.cwd = at(target.text);
      continue;
    }
    const dashC = texts.findIndex((t) => typeof t === 'string' && /^-[a-z]*c$/.test(t));
    if ((name === 'bash' || name === 'sh' || name === 'zsh' || name === 'dash') && dashC >= 0 && depth < 3) {
      const script = args[dashC + 1];
      if (script && !script.raw.dynamic) {
        merge(analyzeShell(script.raw.text, ctx.cwd, env, depth + 1));
      }
      continue;
    }
    if (name === 'eval' && depth < 3) {
      merge(analyzeShell(args.map((a) => a.raw.text).join(' '), ctx.cwd, env, depth + 1));
      continue;
    }

    if (['cp', 'mv', 'rsync', 'install', 'ln', 'scp', 'ditto'].includes(name)) {
      const ti = texts.findIndex((t) => t === '-t' || t === '--target-directory');
      let dest;
      let sources;
      if (ti >= 0) {
        dest = texts[ti + 1];
        sources = operands.filter((o) => o !== args[ti + 1]).map((o) => o.text);
      } else {
        dest = operands.length >= 2 ? operands[operands.length - 1].text : null;
        sources = operands.slice(0, -1).map((o) => o.text);
      }
      if (dest && !/^[^/]*:/.test(dest)) {
        const destAbs = at(dest);
        const intoDir = dest.endsWith('/') || (destAbs && existsSync(destAbs) && safeIsDir(destAbs)) || ti >= 0;
        if (intoDir && destAbs) {
          // Into a folder: what lands is each source's name there (or, for
          // "dir/" and patterns, each thing inside it); the folder itself only
          // gains entries.
          for (const s of sources) for (const t of copyTargets(s, s === null ? null : at(s), destAbs)) write(t);
          result.mkdirs.push(destAbs);
        } else {
          write(dest);
        }
      } else if (dest === null && operands.length) {
        // Unreadable destination: nothing determinable.
      }
      if (name === 'mv') for (const s of sources) remove(s);
      continue;
    }
    if (name === 'tar' || name === 'unzip' || name === 'bsdtar') {
      // Unpacking into a folder (-C dir / -d dir): what lands is unknown.
      const flag = name === 'unzip' ? ['-d'] : ['-C', '--directory'];
      const k = texts.findIndex((t) => flag.includes(t));
      const extracting = name === 'unzip' || texts.some((t) => t && (/^-?[a-zA-Z]*x/.test(t) || t === '--extract' || t === '--get'));
      if (extracting && k >= 0) {
        const into = at(texts[k + 1] ?? null);
        if (into) result.writes.push(into, join(into, '*'));
      }
      continue;
    }
    if (['rm', 'rmdir', 'touch', 'mkdir', 'truncate', 'unlink', 'shred', 'tee'].includes(name)) {
      for (let k = 0; k < args.length; k += 1) {
        const t = args[k].raw.text;
        if (name === 'truncate' && (t === '-s' || t === '--size')) { k += 1; continue; }
        if (name === 'mkdir' && (t === '-m' || t === '--mode')) { k += 1; continue; }
        if (isOption(t)) continue;
        if (['rm', 'rmdir', 'unlink', 'shred'].includes(name)) remove(args[k].text);
        else if (name === 'mkdir') { const abs = at(args[k].text); if (abs) result.mkdirs.push(abs); }
        else write(args[k].text);
      }
      continue;
    }
    if (name === 'chmod' || name === 'chown' || name === 'chgrp') {
      operands.slice(1).forEach((o) => write(o.text));
      continue;
    }
    if (name === 'dd') {
      for (const t of texts) if (t && t.startsWith('of=')) write(t.slice(3));
      continue;
    }
    if (name === 'sed' || name === 'perl' || name === 'gsed') {
      const inPlace = texts.some((t) => t && (/^-[a-zA-Z]*i/.test(t) || t.startsWith('--in-place')));
      if (!inPlace) {
        if (name === 'perl') inlineScript(name, args, texts);
        continue;
      }
      let scriptGiven = false;
      const files = [];
      for (let k = 0; k < args.length; k += 1) {
        const t = args[k].raw.text;
        if (t === '-e' || t === '-f' || t === '--expression' || (name === 'perl' && /^-[a-zA-Z]*e$/.test(t))) { scriptGiven = true; k += 1; continue; }
        if (t === '-i' && name === 'sed' && args[k + 1] && args[k + 1].raw.text === '') { k += 1; continue; }
        if (isOption(t)) continue;
        if (!scriptGiven) { scriptGiven = true; continue; }
        files.push(args[k].text);
      }
      files.forEach(write);
      continue;
    }
    if (name === 'git') {
      let gitDir = ctx.cwd;
      let k = 0;
      while (k < args.length && isOption(args[k].raw.text)) {
        const t = args[k].raw.text;
        if (t === '-C') { gitDir = at(args[k + 1]?.text ?? null); k += 2; continue; }
        if (t.startsWith('--work-tree=')) { gitDir = at(expandWord({ text: t.slice(12), dynamic: args[k].raw.dynamic }, ctx)); k += 1; continue; }
        if (t.startsWith('--git-dir=')) { gitDir = at(expandWord({ text: t.slice(10), dynamic: args[k].raw.dynamic }, ctx)); k += 1; continue; }
        if (t === '-c' || t === '--git-dir' || t === '--work-tree') {
          if (t !== '-c') gitDir = at(args[k + 1]?.text ?? null);
          k += 2;
          continue;
        }
        k += 1;
      }
      const sub = args[k]?.raw.text;
      if (sub && GIT_WRITES.has(sub) && gitDir) {
        if (sub === 'clone') {
          const rest = args.slice(k + 1).filter((a) => !isOption(a.raw.text));
          if (rest.length >= 2) write(rest[rest.length - 1].text ? resolve(gitDir, rest[rest.length - 1].text) : null);
          else if (rest[0]?.text) write(join(gitDir, basename(rest[0].text).replace(/\.git$/, '')));
        } else {
          result.writes.push(gitDir);
        }
      }
      continue;
    }
    if (name === 'bun' && texts.some((t) => t === '-e' || t === '--eval')) {
      inlineScript(name, args, texts);
      continue;
    }
    if (PM.has(name)) {
      let pmCwd = ctx.cwd;
      let sub = null;
      const rest = [];
      for (let k = 0; k < args.length; k += 1) {
        const t = args[k].raw.text;
        const eq = t.indexOf('=');
        const flagName = eq > 0 ? t.slice(0, eq) : t;
        if (['--prefix', '-C', '--dir', '--cwd'].includes(flagName)) {
          pmCwd = at(eq > 0 ? expandWord({ text: t.slice(eq + 1), dynamic: args[k].raw.dynamic }, ctx) : args[k + 1]?.text ?? null);
          if (eq < 0) k += 1;
          continue;
        }
        if (PM_OPTS_WITH_VALUE.has(t)) { k += 1; continue; }
        if (isOption(t)) continue;
        if (sub === null) sub = t;
        else rest.push(args[k]);
      }
      if (name === 'bun' && sub === 'pm' && rest[0]?.raw.text === 'pack') sub = 'pack';
      if (name === 'yarn' && sub === null) sub = 'install';
      if (sub === 'pack' || sub === 'publish') {
        if (packageNameAt(pmCwd).startsWith('@piezas/') || rest.some((a) => isPiezasPackageRef(a.raw.text, pmCwd))) {
          result.sdk.push(`\`${name} ${sub}\` would build a package of Piezas's SDK`);
        }
      }
      if (sub === 'link' || sub === 'ln') {
        if (packageNameAt(pmCwd).startsWith('@piezas/') || rest.some((a) => isPiezasPackageRef(a.raw.text, pmCwd))) {
          result.sdk.push(`\`${name} link\` would replace the published Piezas SDK with a local copy`);
        }
      }
      if (sub && PM_INSTALL.has(sub)) {
        for (const a of rest) {
          const t = a.raw.text;
          const scoped = /^(@piezas\/[^@\s]+)@(.+)$/.exec(t);
          if (scoped) {
            const problem = piezasSpecProblem(scoped[2]);
            if (problem) result.sdk.push(`installing ${scoped[1]}@${scoped[2]}: it ${problem}`);
          } else if (pathish(t) && isPiezasPackageRef(t, pmCwd)) {
            result.sdk.push(`installing the Piezas SDK from ${t} instead of from npm`);
          }
        }
      }
      if (sub === 'pkg' && rest[0]?.raw.text === 'set') {
        for (const a of rest.slice(1)) {
          const m = /@piezas\/[^=]+=(.+)$/.exec(a.raw.text);
          if (m && piezasSpecProblem(m[1])) result.sdk.push(`setting ${a.raw.text}: not the published version`);
        }
      }
      if (sub && !PM_READ_ONLY.has(sub) && pmCwd) result.outsideCwd.push(pmCwd);
      continue;
    }
    if (name === 'go') {
      const sub = operands[0]?.raw.text;
      if (sub && GO_WRITES.has(sub) && ctx.cwd) result.outsideCwd.push(ctx.cwd);
      continue;
    }
    if (OUTSIDE_RUNNERS.has(name)) {
      if (name === 'gofmt' || name === 'goimports') {
        if (texts.includes('-w')) operands.forEach((o) => write(o.text));
        continue;
      }
      if (ctx.cwd) result.outsideCwd.push(ctx.cwd);
      continue;
    }
    if (['node', 'python', 'python3', 'ruby', 'deno'].includes(name)) {
      // A script passed inline (perl and bun are handled above, with sed and
      // the package managers).
      inlineScript(name, args, texts);
    }
  }
  return result;
}

function safeIsDir(p) {
  try { return lstatSync(p).isDirectory(); } catch { return false; }
}

// --- the verdict -------------------------------------------------------------

// A whole vendored copy (or the installed package folder): deleting it is the
// clean-up doctor and deploy recommend, so a delete is fine. Creating or
// changing one is not.
const VENDORED_COPY_PATH = [
  /(^|\/)vendor\/[^/]*piezas/i,
  /(^|\/)vendor\/@piezas(\/|$)/,
  /piezas-sdk[^/]*\.(?:tgz|tar\.gz|tar)$/i,
  /(^|\/)node_modules\/@piezas(\/[^/]+)?$/,
];

export function isVendoredCopyPath(relPosix) {
  return VENDORED_COPY_PATH.some((re) => re.test(relPosix));
}

// ownerRecordTarget — does writing `real` (how: 'write' | 'delete') touch the
// owner's records in the project at realRoot? The record files themselves,
// the .piezas folder as a whole, and a pattern right inside it (cp x/* .piezas/).
function ownerRecordTarget(real, realRoot, how, env = process.env) {
  // Compared as the file system sees names (case-insensitive on macOS and Windows).
  const rel = relKey(real, realRoot, env);
  if (rel === null) return null;
  const f = (p) => foldPath(p, env);
  const state = f(STATE_DIR);
  if (rel === f(`${STATE_DIR}/${OUTSIDE_RECORD}`)) return 'outside';
  if (rel === f(`${STATE_DIR}/${OWNER_APPROVALS_FILE}`) && how !== 'delete') return 'records';
  // The minted-key record decides which key a deploy removes: Piezas only.
  if (rel === f(`${STATE_DIR}/${KEY_MINT_FILE}`)) return 'records';
  // "This project deployed this app" (its token) and the link question
  // waiting for the owner's own "link to <name>": Piezas only.
  if (rel === f(`${STATE_DIR}/${DEPLOY_LINK_FILE}`) || rel === f(`${STATE_DIR}/${LINK_CONFIRM_FILE}`)) return 'records';
  // The hooks' own marker (they ran here): it decides whether the AI may relay
  // the owner's words, so only the hooks write it.
  if (rel === f(`${STATE_DIR}/guard.json`)) return 'records';
  // The delivery protocol's state holds the owner's approvals too. Once it
  // exists the protocol guard closes it; before that, only the piezas command itself
  // creates it (init, phase init), never a file write.
  if (rel === f(`${STATE_DIR}/state.json`) && how !== 'delete' && !existsSync(real)) return 'records';
  // The quality scan's record, and its folder except the scanner's answer.
  const qualityDir = f(`${STATE_DIR}/${QUALITY_SCAN_DIR}`);
  if (rel === f(`${STATE_DIR}/${QUALITY_ATTESTATION_FILE}`) || rel === qualityDir) return 'quality';
  if (rel.startsWith(`${qualityDir}/`) && rel !== f(`${STATE_DIR}/${QUALITY_SCAN_DIR}/${QUALITY_FINDINGS_FILE}`)) return 'quality';
  if (rel === state) return 'records';
  if (rel.startsWith(`${state}/`) && !rel.slice(state.length + 1).includes('/') && GLOB.test(basename(real))) return 'records';
  return null;
}

// workspaceVerdict — the guard's answer for one tool call, or null to let the
// other rules decide. options: { cwd (the session's folder), workdir, tool,
// file, content, deleting (an apply_patch "Delete File"), command, sessionId,
// env }.
//
// The guard refuses a write outside the app's folder only when it is sure
// which folder that is: the session runs in the project (or inside it). A
// session opened in a folder ABOVE projects (a folder of repos) is not one
// app's session, so its other folders stay open; a write that lands inside
// a Piezas project still gets that project's package and record rules.
export function workspaceVerdict(options = {}) {
  const env = options.env ?? process.env;
  const cwd = resolve(options.cwd || process.cwd());
  const root = projectAt(cwd);
  const realRoot = root ? realish(root) : null;
  let open = null;
  const openDirs = () => (open ??= openWriteDirs(env));
  // The project a target lands in (computed once per folder, per call).
  const projectCache = new Map();
  const projectOf = (real) => {
    if (realRoot && isInside(real, realRoot)) return realRoot;
    const dir = dirname(real);
    if (!projectCache.has(dir)) {
      const found = projectAt(dir);
      projectCache.set(dir, found ? realish(found) : null);
    }
    return projectCache.get(dir);
  };

  // -> 'record' | 'records' | 'package' | 'hookstate' | 'inside' | 'open' | 'outside'
  const classify = (abs, how = 'write') => {
    const real = realish(abs);
    // The hook entries' private folder (the plugin's marks): never the AI's.
    if (how !== 'mkdir' && inHookStateDir(real, env)) return 'hookstate';
    const project = projectOf(real);
    if (project) {
      if (how !== 'mkdir') {
        const record = ownerRecordTarget(real, project, how, env);
        if (record === 'outside') return how === 'delete' ? 'inside' : 'record';
        if (record === 'quality') return 'quality';
        if (record) return 'records';
      }
      const rel = foldPath(relative(project, real).split(sep).join('/'), env);
      if (isPiezasPackagePath(rel)) return how === 'delete' && isVendoredCopyPath(rel) ? 'inside' : 'package';
      if (project === realRoot || !realRoot) return 'inside';
    }
    if (!realRoot) return 'open'; // not sure which app this session is: nothing is "outside"
    if (openDirs().some((d) => isInside(real, d)) || isClaudeMemory(real, env)) return 'open';
    return 'outside';
  };
  const block = (reason) => ({ exitCode: 2, verdict: 'block', reason });
  // The owner's "allow outside changes" is recorded in the session's project
  // (for a session above projects: the one the hooks found below it).
  let allowRoot;
  const outsideOk = () => {
    if (allowRoot === undefined) allowRoot = root ?? workspaceRoot(cwd);
    return !!allowRoot && outsideAllowed(allowRoot, options.sessionId);
  };
  const shownRoot = root ?? cwd;

  const tool = options.tool || '';
  if (tool === 'Bash') {
    const command = String(options.command || '');
    if (!command) return null;
    const workdir = options.workdir ? resolve(cwd, options.workdir) : cwd;
    const targets = []; // [abs, how]
    // Codex sometimes runs apply_patch through the shell: its file headers are
    // writes too.
    if (command.includes('*** Begin Patch')) {
      let last = null;
      for (const m of command.matchAll(/^\*\*\* (Add|Update|Delete) File: (.+)$|^\*\*\* Move to: (.+)$/gm)) {
        const abs = resolve(workdir, (m[2] ?? m[3]).trim());
        targets.push([abs, m[1] === 'Delete' ? 'delete' : 'write']);
        // A move takes the file away from where it was.
        if (m[3] && last) targets.push([last, 'delete']);
        last = m[2] ? abs : null;
      }
    }
    if (/outside-changes\.json/i.test(command)) return block(OUTSIDE_RECORD_BLOCK);
    if (command.toLowerCase().includes(OWNER_APPROVALS_FILE)) return block(OWNER_RECORDS_BLOCK);
    if ([KEY_MINT_FILE, DEPLOY_LINK_FILE, LINK_CONFIRM_FILE, 'guard.json'].some((name) => command.toLowerCase().includes(name)) && /[>|]|\b(?:tee|cp|mv|rm|sed|perl|python3?|node|ruby|truncate|touch|dd|install|ln)\b/.test(command)) return block(OWNER_RECORDS_BLOCK);
    // The manifest's link to the app (appName, deploy.appId/url/slug, the
    // test copy): only the piezas commands write it.
    if (manifestLinkShellWrite(command)) return block(MANIFEST_LINK_BLOCK);
    if (MENTIONS_QUALITY_RECORD.test(command) && QUALITY_WRITEISH.some((re) => re.test(command))) return block(QUALITY_RECORD_BLOCK);
    const shell = analyzeShell(stripHeredocBodies(command), workdir, env);
    for (const w of shell.writes) targets.push([w, 'write']);
    for (const w of shell.deletes) targets.push([w, 'delete']);
    for (const w of shell.mkdirs) targets.push([w, 'mkdir']);
    const sdk = [...shell.sdk];
    // A command that writes package.json (cat > package.json <<EOF) carries the content.
    if (/package\.json/.test(command) && /"@piezas\/[^"]+"\s*:\s*"/.test(command)) {
      const bad = depSpecsInText(command);
      if (bad.length) sdk.push(`package.json would declare ${bad.join(', ')}`);
    }
    const kinds = targets.map(([abs, how]) => [abs, classify(abs, how)]);
    if (kinds.some(([, k]) => k === 'record')) return block(OUTSIDE_RECORD_BLOCK);
    if (kinds.some(([, k]) => k === 'records')) return block(OWNER_RECORDS_BLOCK);
    if (kinds.some(([, k]) => k === 'quality')) return block(QUALITY_RECORD_BLOCK);
    if (kinds.some(([, k]) => k === 'hookstate') || (/piezas-hooks/i.test(command) && shell.unknown > 0)) return block(HOOK_STATE_BLOCK);
    if (sdk.length && !outsideOk()) return block(sdkBlockReason(sdk[0]));
    const pkg = kinds.find(([, k]) => k === 'package');
    if (pkg && !outsideOk()) {
      const rel = toRel(pkg[0], realRoot ?? projectOf(realish(pkg[0])));
      return block(isHookPath(rel)
        ? hooksBlockReason(`it changes ${rel}`)
        : sdkBlockReason(`it writes into Piezas's own package (${rel})`));
    }
    for (const [abs, how] of targets) {
      if (how === 'mkdir') continue;
      const real = realish(abs);
      const project = projectOf(real);
      const problem = project && fileProblem(real, project, how === 'delete' ? 'shell-delete' : 'shell-write', null, env);
      if (problem && !outsideOk()) return block(hooksBlockReason(problem));
    }
    // What a list of targets cannot show: git putting files back, package
    // managers changing the piezas tools, deleters run through npx, find -delete.
    {
      const project = realRoot ?? (workdir ? projectAt(workdir) : null);
      const problem = project && shellProblem(stripHeredocBodies(command), workdir, realish(project), shell, env);
      if (problem && !outsideOk()) return block(hooksBlockReason(problem));
    }
    const outside = [...new Set([
      ...kinds.filter(([, k]) => k === 'outside').map(([abs]) => abs),
      ...shell.outsideCwd.filter((d) => classify(d, 'mkdir') === 'outside'),
    ])];
    if (outside.length && !outsideOk()) return block(outsideBlockReason(outside, shownRoot));
    return null;
  }

  if (!options.file) return null;
  const abs = resolve(cwd, options.file);
  const kind = classify(abs, options.deleting ? 'delete' : 'write');
  if (kind === 'record') return block(OUTSIDE_RECORD_BLOCK);
  if (kind === 'records') return block(OWNER_RECORDS_BLOCK);
  if (kind === 'quality') return block(QUALITY_RECORD_BLOCK);
  if (kind === 'hookstate') return block(HOOK_STATE_BLOCK);
  if (kind === 'package') {
    if (outsideOk()) return null;
    const rel = toRel(abs, realRoot ?? projectOf(realish(abs)));
    return block(isHookPath(rel) ? hooksBlockReason(`${rel} runs the Piezas guardrails`) : sdkBlockReason(`${rel} is part of Piezas's own package`));
  }
  if (kind === 'inside' && basename(abs) === MANIFEST_FILE && !options.deleting) {
    const after = typeof options.proposed === 'string' ? options.proposed : typeof options.content === 'string' ? options.content : null;
    let before = null;
    try { before = readFileSync(abs, 'utf-8'); } catch { /* a new manifest */ }
    if (manifestLinkChanged(before, after)) return block(MANIFEST_LINK_BLOCK);
  }
  if (kind === 'inside') {
    const real = realish(abs);
    const project = projectOf(real);
    // The edit tools: judged by the whole file the change would leave.
    const proposed = typeof options.proposed === 'string' ? options.proposed : null;
    const problem = project && fileProblem(real, project, options.deleting ? 'delete' : 'write', proposed, env);
    if (problem && !outsideOk()) return block(hooksBlockReason(problem));
  }
  if (kind === 'outside') return outsideOk() ? null : block(outsideBlockReason([abs], shownRoot));
  if (kind === 'inside' && basename(abs) === 'package.json' && typeof options.content === 'string') {
    const bad = depSpecsInText(options.content);
    if (bad.length && !outsideOk()) return block(sdkBlockReason(`package.json would declare ${bad.join(', ')}`));
  }
  return null;
}

// The project's own hook file, and the CLI it loads.
function isHookPath(relPosix) {
  return /^\.piezas\/hooks(\/|$)/.test(relPosix) || /(^|\/)node_modules\/piezas(\/|$)/.test(relPosix);
}

function toRel(abs, realRoot) {
  return relative(realRoot, realish(abs)).split(sep).join('/');
}

// depSpecsInText — "@piezas/x": "<spec>" pairs in text that are not published versions.
export function depSpecsInText(text) {
  const bad = [];
  for (const m of String(text).matchAll(/"(@piezas\/[^"]+)"\s*:\s*"([^"]*)"/g)) {
    if (piezasSpecProblem(m[2])) bad.push(`"${m[1]}": "${m[2]}"`);
  }
  return bad;
}
